svg.script:

function movePointer(pointerId, arrowId, newX) {
  const pointer = document.getElementById(pointerId);
  const arrow = document.getElementById(arrowId);
  pointer.setAttribute("x", newX);
  arrow.setAttribute("x1", newX + 5);
  arrow.setAttribute("x2", newX + 5);
}

const steps = [
  { tag: "show-key"},
  { tag: "put-arrows", lo: 0, mid: 4, hi: 8 },
  { tag: "put-arrows", lo: 4, mid: 5, hi: 8 },
  { tag: "put-arrows", lo: 5, mid: 5, hi: 5 }
];

const positions = [50, 100, 150, 200, 250, 300, 350, 400, 450];
let stepIndex = 0;

function animateStep() {
  if (stepIndex >= steps.length) return;

  const step = steps[stepIndex];

  console.log(step.tag);

  if (step.tag == "show-key") {
    document.getElementById("given-key-text").setAttribute("visibility", "visible");
    document.getElementById("given-key-value").setAttribute("visibility", "visible");
    return;
  }

  if (step.tag == "put-arrows") {
    lo = step.lo;
    mid = step.mid;
    hi = step.hi;

    movePointer("lo", "lo-arrow", positions[lo]);
    movePointer("mid", "mid-arrow", positions[mid]);
    movePointer("hi", "hi-arrow", positions[hi]);
    stepIndex++;
    setTimeout(animateStep, 1000);
    return;
  }
}

// Start animation
setTimeout(animateStep, 1000);
